WITH base AS (SELECT id, session_id, event_type, page, duration_sec, ROUND(duration_sec * 0.9, 2) AS duration_sec_scaled, INITCAP(TRIM(page)) AS page_title, COALESCE(page, 'OTHER') AS page_clean FROM web_events WHERE duration_sec > 285) SELECT CASE WHEN duration_sec_scaled >= 86 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_scaled_tier, CASE WHEN duration_sec >= 379 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, SUM(CASE WHEN page = '/cart' THEN duration_sec_scaled ELSE 0 END) AS cart_duration_sec_scaled, AVG(duration_sec) FILTER (WHERE event_type = 'purchase') AS purchase_avg_duration_sec, COUNT_IF(page = '/product') AS product_events, ROUND(SUM(duration_sec_scaled) / NULLIF(COUNT(CASE WHEN event_type = 'purchase' THEN 1 END), 0), 2) AS duration_sec_scaled_per_purchase FROM base GROUP BY CASE WHEN duration_sec_scaled >= 86 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN duration_sec >= 379 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY cart_duration_sec_scaled ASC;
